update public.bots
set description = 'Experimento em shadow com tendência compradora H1/M15, gatilho M5 e risco reduzido na sessão de maior estabilidade histórica.',
    strategy_description = E'- Status: experimento bloqueado em shadow; os números históricos são exploratórios e exigem forward test independente.\n- Mercado e gráfico: ouro/dólar (XAUUSD) no M5.\n- Tendência longa: MME20 e MME50 de candles H1 completos; exige inclinação compradora e distância mínima de 0,7 ATR(H1).\n- Tendência curta: MME9 e MME21 de candles M15 completos, alinhadas com a direção H1.\n- Gatilho: pullback e rejeição compradora da MME9 no M5, com MME9 acima da MME21.\n- Horário de entrada: 13:00–15:59 UTC; no horário de Brasília corresponde normalmente a 10:00–12:59 (UTC-3).\n- Gestão: no máximo 2 entradas por dia, stop técnico de 1,2 ATR(M5), alvo único de 0,75R, somente 50% do risco padrão por operação e encerramento após 12 candles (60 minutos).\n- Experimento histórico exploratório: a seleção compradora reduziu operações e melhorou a assimetria entre ganho e perda, mas não constitui promessa de desempenho futuro.\n- Limitação: os mesmos dados já foram usados para comparação de variantes; a decisão de ativação depende de forward test ainda não observado.'
where id = 'bot-7';
